"""Copy every settlement from the Clearwell Settlements API into settlements.jsonl."""
import argparse
import json
import time
import urllib.error
import urllib.request

QUERY = """query Settlements($first: Int, $after: String) {
  settlements(first: $first, after: $after) {
    nodes { id batchDate amountCents currency status }
    pageInfo { endCursor hasNextPage }
  }
}"""

PAGE_SIZE = 100


class GraphQLError(RuntimeError):
    pass


def graphql(url, query, variables=None):
    body = json.dumps({
        "query": query,
        "operationName": "Settlements",
        "variables": variables or {},
    }).encode()
    while True:
        # Rebuild the request each attempt so a retry is byte-for-byte identical.
        req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                result = json.load(resp)
        except urllib.error.HTTPError as e:
            if e.code != 429:
                raise
            try:
                delay = float(e.headers.get("Retry-After", "1"))
            except ValueError:
                delay = 1.0
            time.sleep(delay)
            continue
        if result.get("errors"):
            raise GraphQLError(result["errors"])
        return result["data"]


def fetch_settlements(url):
    """Traverse every page, keyed by id, keeping the last version received."""
    by_id = {}
    after = None
    restarted = False
    while True:
        variables = {"first": PAGE_SIZE}
        if after is not None:
            variables["after"] = after
        try:
            data = graphql(url, QUERY, variables)
        except GraphQLError:
            # A malformed or expired cursor: start again from the beginning.
            if after is not None and not restarted:
                restarted = True
                after = None
                continue
            raise
        connection = data["settlements"]
        for settlement in connection["nodes"]:
            by_id[settlement["id"]] = settlement
        page_info = connection["pageInfo"]
        if not page_info["hasNextPage"]:
            break
        # Short or empty pages are not the end; keep going until hasNextPage is false.
        after = page_info["endCursor"]
    return list(by_id.values())


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="settlements.jsonl")
    args = ap.parse_args()
    settlements = fetch_settlements(f"{args.base_url.rstrip('/')}/v2/graphql")
    with open(args.out, "w", encoding="utf-8") as f:
        for s in settlements:
            f.write(json.dumps(s) + "\n")
    print(f"reconciled {len(settlements)} settlements")


if __name__ == "__main__":
    main()

